        if vy > 0:
            sandbox.apply_force_to_seat(0, 42.0)

        # Apply horizontal force when moving downward (vy < 0), in the direction of vx
        if vy < 0:
            if vx > 0:
                fx = 42.0
            elif vx < 0:
                fx = -42.0
            else:
                fx = 0
            # Apply force if horizontal speed is sufficient
            if abs(vx) > speed_threshold:
                sandbox.apply_force_to_seat(fx, 0)
            else:
                # Apply impulse to nudge position when speed is too low
                sandbox.apply_impulse_to_seat(fx * 0.1, 0)
    else:
        # Stabilize within target zone
        if not (9.35 <= pos.x <= 10.65):
            # Apply horizontal force to move toward target x range
            if pos.x < 9.35:
                fx = 42.0
            elif pos.x > 10.65:
                fx = -42.0
            else:
                fx = 0
            if abs(vx) > speed_threshold:
                sandbox.apply_force_to_seat(fx, 0)
            else:
                sandbox.apply_impulse_to_seat(fx * 0.1, 0)
        else:
            # Counteract horizontal velocity to stabilize in target x range
            fx = -vx * 10.0
            if fx > 42.0:
                fx = 42.0
            elif fx < -42.0:
                fx = -42.0
            sandbox.apply_force_to_seat(fx, 0)
